def seed_salary_benchmarks(cursor):
    """Seed and upgrade the salary_benchmarks table with full intelligence catalog."""
    cursor.execute("""
        CREATE TABLE IF NOT EXISTS salary_benchmarks (
            id INT AUTO_INCREMENT PRIMARY KEY,
            job_role VARCHAR(150) NOT NULL,
            experience_level VARCHAR(50) NOT NULL,
            location VARCHAR(100) NOT NULL,
            primary_technology VARCHAR(100) NOT NULL,
            industry VARCHAR(100) DEFAULT 'Technology',
            salary_min FLOAT NOT NULL,
            salary_median FLOAT NOT NULL,
            salary_avg FLOAT NOT NULL,
            salary_max FLOAT NOT NULL,
            sample_size INT DEFAULT 100,
            is_demo_data BOOLEAN DEFAULT TRUE,
            currency VARCHAR(20) DEFAULT 'INR (LPA)',
            updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
            INDEX idx_sb_role (job_role),
            INDEX idx_sb_exp (experience_level),
            INDEX idx_sb_loc (location),
            INDEX idx_sb_tech (primary_technology)
        )
    """)

    # Check count - if existing count is small (<500), refresh with full catalog
    cursor.execute("SELECT COUNT(*) AS cnt FROM salary_benchmarks")
    row = cursor.fetchone()
    count = row["cnt"] if isinstance(row, dict) else row[0]

    if count < 500:
        cursor.execute("TRUNCATE TABLE salary_benchmarks")
        insert_sql = """
            INSERT INTO salary_benchmarks
            (job_role, experience_level, location, primary_technology, industry, salary_min, salary_median, salary_avg, salary_max, sample_size, is_demo_data)
            VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, TRUE)
        """
        for item in SALARY_BENCHMARKS_SEED:
            cursor.execute(insert_sql, (
                item["job_role"], item["experience_level"], item["location"], item["primary_technology"],
                item.get("industry", "Technology"), item["salary_min"], item["salary_median"], item["salary_avg"],
                item["salary_max"], item.get("sample_size", 100)
            ))
